/**
 * Motor de búsqueda y consulta semántica de alta precisión
 */
exportar la función asíncrona searchSentences(
  consulta: cadena,
  filtros: SearchFilterOptions = {}
): Promesa<{ resultados: SentenceItem[]; total:número; ¿Partidas semánticas?: Coincidencia de explicación semántica[] }> {
  const todo = espera cargarSentencias();
  const normalizedQuery = normalizeText(consulta);
  const queryTokens = consulta normalizada? normalizedQuery.split('').filter(Booleano): [];

  constante {
    cefr = 'todos',
    sección = 'todos',
    categoría = 'todos',
    subcategoría = 'todos',
    gramática = 'todos',
    formalidad = 'todos',
    límite = 50,
    desplazamiento = 0,
  } = filtros;

  // pase de filtro
  dejar filtrado = all.filter(s => {
    si (cefr! == 'todos' && s.cefr! == cefr) devuelve falso;
    if (sección! == 'todos' && s.sección! == sección) devuelve falso;
    si (categoría! == 'todos' && s.categoría! == categoría) devuelve falso;
    si (subcategoría! == 'todos' && s.subcategoría! == subcategoría) devuelve falso;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) devuelve falso;
    if (formalidad! == 'todos' && s.formalidad.toLowerCase()!== formalidad.toLowerCase()) devuelve falso;
    devolver verdadero;
  });

  si (! consulta normalizada) {
    total constante = longitud.filtrada;
    const paginado = filtrado. sector (desplazamiento, desplazamiento + límite);
    return {resultados: paginados, total};
  }

  // Algoritmo de puntuación
  interfazScoredItem {
    artículo: artículo de oración;
    puntuación: número;
    aspecto: SemanticExplanationMatch['matchedAspect'];
  }

  puntuación constante: ScoredItem[] = [];

  para (const s de filtrado) {
    deja puntuación = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'inglés';

    const normaEn = normalizeText(es.inglés);
    const normaEg = normalizeText(s.arabicEg);
    const normaFusha = normalizeText(s.arabicFusha);
    const normaGramática = normalizeText(s.grammar);
    const normaPropósito = normalizeText(s.propósito);

    // Coincidencia exacta de la oración completa
    if (normaEn === consulta normalizada) {
      puntuación += 100;
      aspecto emparejado = 'inglés';
    } else if (normEg === consulta normalizada) {
      puntuación += 95;
      matchedAspect = 'árabe-por ejemplo';
    } más si (normFusha === consulta normalizada) {
      puntuación += 90;
      aspecto emparejado = 'árabe-fusha';
    }

    //La subcadena contiene
    if (normEn.includes(normalizedQuery)) {
      puntuación += 50;
      aspecto emparejado = 'inglés';
    } else if (normEg.includes(normalizedQuery)) {
      puntuación += 45;
      matchedAspect = 'árabe-por ejemplo';
    } else if (normFusha.includes(normalizedQuery)) {
      puntuación += 40;
      aspecto emparejado = 'árabe-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      puntuación += 35;
      aspecto emparejado = 'gramática';
    } else if (normPurpose.includes(normalizedQuery)) {
      puntuación += 30;
      aspecto emparejado = 'concepto';
    }

    // Coincidencia de tokens
    dejar tokenMatches = 0;
    para (token constante de queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    puntuación += tokenMatches;

    si (puntuación > 0) {
      scoring.push({ elemento: s, puntuación, aspecto: matchedAspect });
    }
  }

  scoring.sort((a, b) => b.score - a.score);

  // Coincidencias de explicación semántica para los elementos principales
  const semanticMatches: SemanticExplanationMatch[] = scoring.slice(0, 5).map(s => {
    let matiz = '';
    if (s.item.grammar.toLowerCase().includes('pasado continuo')) {
      matiz = 'El pasado continuo muestra que un evento estaba en curso en un momento específico en el pasado.';
    } else if (s.item.grammar.toLowerCase().includes('presente perfecto continuo')) {
      matiz = 'El presente perfecto continuo enfatiza el tiempo del pasado y continúa hasta el momento de hablar.';
    } else if (s.item.grammar.toLowerCase().includes('futuro perfecto')) {
      matiz = 'El futuro perfecto expresa que un evento se completará antes de un momento específico en el futuro.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      matiz = 'La forma de solicitud indirecta es el pináculo de la etiqueta diplomática en la comunicación inglesa.';
    }
    devolver {
      oración: s.item,
      puntuación de similitud: Math.min(100, s.score),
      matizExplicaciónAr: matiz,
      aspecto emparejado: s.aspecto,
    };
  });

  total constante = puntuado. longitud;
  const paginado = anotado.slice(desplazamiento, desplazamiento + límite).map(s => s.item);

  devolver {
    resultados: paginados,
    totales,
    coincidencias semánticas,
  };
}

